class Solution:
    def maximumLength(self, s: str) -> int:
        if len(set(s)) == len(s):
            return -1

        i = len(s) - 3
        if i < 0:
            return -1

        d = {}
        count = 0
        j = i

        while j < len(s):
            if len(set(s[count:count + 1])) == 1:
                if s[count + 1] in d:
                    d[s[count + 1]] += 1
                else:
                    d[s[count + 1]] = 1

                if d[s[count + 1]] == 3:
                    return count + 1

            count += 1
            j += 1

        return -1

